4	 * Prints a single JSON line with { serverId, hostname, family, planId }.
5	 */
6	import { db } from "/opt/nxeon/lib/db";
7	
8	const NODE2 = "cmto2zpwh0000hltqk6oaxy69";
9	const OPS_USER = "cmrztujaw0002hlazl58i3lsi";
10	
11	(async () => {
12	  const family = process.argv[2];
13	  if (!family) throw new Error("usage: provision.ts <family>");
14	
15	  const gamePlan = await db.gamePlan.findFirst({
16	    where: { gameFamily: family },
17	    orderBy: { priceCents: "asc" },
18	  });
19	  if (!gamePlan) {
20	    console.log(JSON.stringify({ family, skip: "no-gameplan" }));
21	    await db.$disconnect();
22	    return;
23	  }
24	
25	  // hostname: /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i and <= 40 chars
26	  const stamp = Date.now().toString(36);
27	  const hostname = `t-${family.replace(/[^a-z0-9]/gi, "")}-${stamp}`.slice(0, 40).replace(/-$/, "");
28	
29	  const server = await db.server.create({
30	    data: {
31	      name: hostname,
32	      hostname,
33	      userId: OPS_USER,
34	      planId: gamePlan.basePlanId,
35	      osTemplateId: gamePlan.osTemplateId,
36	      gamePlanId: gamePlan.id,
37	      nodeId: NODE2,
38	      isFree: true,
39	      termPromoPercent: 100,
40	    },
41	  });
42	  await db.job.create({ data: { type: "PROVISION", serverId: server.id } });
43	
44	  console.log(
45	    JSON.stringify({
46	      serverId: server.id,
47	      hostname,
48	      family,
49	      planId: gamePlan.id,
50	      planName: gamePlan.name,
51	    })
52	  );
53	  await db.$disconnect();
54	})().catch((e) => {
55	  console.error(e);
56	  process.exit(1);
57	});
