13	
14	(async () => {
15	  const serverId = process.argv[2];
16	  if (!serverId) throw new Error("usage: info.ts <serverId>");
17	  const s = await db.server.findUnique({
18	    where: { id: serverId },
19	    select: {
20	      id: true,
21	      hostname: true,
22	      status: true,
