1	/**
2	 * Sweep harness: delete a throwaway test server's DB rows COMPLETELY.
3	 * Refuses to touch anything that isn't one of this sweep's own servers
4	 * (ops user + hostname prefix "t-"), so it can never hit a real customer row.
5	 * Usage: npx tsx teardown-db.ts <serverId>
6	 */
7	import { db } from "/opt/nxeon/lib/db";
8	
9	const OPS_USER = "cmrztujaw0002hlazl58i3lsi";
10	
11	(async () => {
12	  const serverId = process.argv[2];
13	  if (!serverId) throw new Error("usage: teardown-db.ts <serverId>");
14	  const s = await db.server.findUnique({
15	    where: { id: serverId },
16	    select: { id: true, hostname: true, userId: true, vmid: true, nodeId: true },
17	  });
18	  if (!s) {
19	    console.log(JSON.stringify({ serverId, result: "already-gone" }));
20	    await db.$disconnect();
21	    return;
22	  }
23	  // Hard safety gate — this sweep only ever created rows shaped like this.
24	  if (s.userId !== OPS_USER || !/^t-[a-z0-9]+-[a-z0-9]+$/.test(s.hostname)) {
25	    throw new Error(
26	      `REFUSING to delete ${s.id} (${s.hostname}): not a sweep-created throwaway server`
27	    );
28	  }
29	
30	  const pf = await db.portForward.deleteMany({ where: { serverId } });
31	  const jobs = await db.job.deleteMany({ where: { serverId } });
32	  // Anything else that could hold an FK to Server — delete defensively but only
33	  // for this row. Unknown models are skipped silently.
34	  for (const model of [
35	    "backup",
36	    "serverMetric",
37	    "gameSchedule",
38	    "notification",
39	  ] as const) {
40	    try {
41	      // @ts-expect-error dynamic model access, guarded by try/catch
42	      await db[model].deleteMany({ where: { serverId } });
43	    } catch {
44	      /* model doesn't exist or has no serverId — fine */
45	    }
46	  }
47	  await db.server.delete({ where: { id: serverId } });
48	  console.log(
49	    JSON.stringify({ serverId, hostname: s.hostname, vmid: s.vmid, deletedForwards: pf.count, deletedJobs: jobs.count, result: "deleted" })
50	  );
51	  await db.$disconnect();
52	})().catch((e) => {
53	  console.error(String(e?.message ?? e));
54	  process.exit(1);
55	});
