import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { connectionTarget, serverRootPassword } from "../lib/sftp";
import {
  familyFor,
  schemaFor,
  validateConfig,
  GAME_CONFIG_VERSION,
} from "../lib/game-config";
import { controlSpec } from "../lib/game-control";
import { Client, type ClientChannel, type SFTPWrapper } from "ssh2";
import type { Job } from "@prisma/client";

/**
 * GAME_CONFIG handler — apply a game server's customization (variant + settings).
 *
 * `worker/index.ts` owns the job loop and its `handlers` map; wire this in there:
 *   GAME_CONFIG: gameConfigApply,
 *
 * Ownership + validation happen at enqueue time (lib/actions-game-config.ts), so
 * this handler trusts `Server.gameVariant` / `Server.gameConfig`.
 *
 * TWO PATHS:
 *  - DEFAULT (simulation): records an "applied" marker on `Server.gameConfig` and
 *    notifies the user. No SSH, no VM mutation. This runs under SANDBOX and, in
 *    production, for any family not yet verified (see below).
 *
 *  - REAL: actually pushes the settings to the live game server over SSH. Runs
 *    per-family (see `REAL_APPLY_FAMILIES`) rather than one blanket switch — a
 *    family's real path is deliberately non-destructive (read-modify-write for
 *    key=value files, or — for images like Palworld's that regenerate their
 *    config from env vars on every boot — a full container recreation with
 *    rollback on failure; never clobbers a config it can't find/parse) and
 *    fully wrapped in try/catch so a failure notifies the user but never
 *    crashes the worker. `ENABLE_REAL_GAMECFG=1` additionally force-enables
 *    every family at once, for whenever the rest have been confirmed too.
 *
 * Enable a family's real path only once its config paths / service names / apply
 * function have been confirmed for the actual game-server image — see
 * `REAL_APPLY_FAMILIES`'s own comment for what "confirmed" means in practice.
 */

/** Force-enables every family's real path at once — set only once ALL of them
 *  have been individually confirmed, not as a way to unblock just one. */
const REAL_APPLY_ENABLED = !SANDBOX && process.env.ENABLE_REAL_GAMECFG === "1";

/**
 * Families whose real-apply path has been individually built AND verified
 * against the actual production image/container, so it's safe to run even
 * while `ENABLE_REAL_GAMECFG` stays off for everyone else.
 *
 * "verified" here means: confirmed live, end-to-end, against a real running
 * container — not just "the code looks right". `palworld` was added
 * 2026-09-05 after the previous version of `applyPalworld` was found to
 * silently regenerate-then-lose its own writes (see that function's comment);
 * the replacement was verified by actually recreating a live container with
 * an updated setting and reading the resulting config back off disk.
 *
 * `minecraft` added 2026-09-06: verified against a real throwaway server on
 * node-2 (provisioned, applied `difficulty` + `online-mode` via
 * `applyRealConfig` directly, read `/opt/mc/server.properties` back off disk
 * and confirmed both values, then destroyed the VM). The path-detection
 * TODO on `applyMinecraft` is resolved for the current image: the host-side
 * bind mount (`/opt/mc` -> `/data`) puts server.properties somewhere
 * `remoteLocate`'s `find` over /opt already reaches. One real, non-blocking
 * gap found: `mcrcon` is not installed on the image, so today every setting
 * falls back to "restart to apply" — correctly reported as such, never
 * silently claimed live — rather than the live-RCON push `tryMinecraftRcon`
 * would otherwise attempt for difficulty/whitelist/etc.
 *
 * `rust` added 2026-09-06 by the whole-catalog integrity sweep, after
 * `applyRust` was found to be writing a `server.cfg` that (a) does not exist on
 * this image and (b) would have been ignored even if it did — see that
 * function's own comment for the two live proofs. The replacement recreates the
 * container from `RUST_SERVER_*` env vars, and was verified by reading **every
 * field in the Rust schema back off the live running game** via its own RCON,
 * not off a config file: `server.hostname: "NXEON SWEEP RUST"`,
 * `server.maxplayers: "42"`, `server.worldsize: "4000"`, `server.pve: "True"`,
 * and `server.seed: "12345"` still at its old value — proving untouched
 * settings survive the recreate. Independently corroborated by the server's own
 * boot log, whose occlusion grid went 1750 -> 2000 (worldsize/2) across the
 * change. One real caveat, reported to the customer in the apply's own notes
 * rather than hidden: Rust reloads its entire map on restart, so an apply takes
 * that server offline for several minutes — far longer than Palworld's seconds.
 *
 * `valheim` added 2026-09-06 by the same sweep. Its old implementation was the
 * worst-behaved of the three pre-written ones — it wrote a launch-args file
 * nothing read and returned `ok: true`, so the customer was told "Game settings
 * applied" while the server was untouched. The replacement recreates the
 * container from `WORLD_NAME` + `SERVER_ARGS`, and was verified against the
 * REAL RUNNING PROCESS's argv (`-world NxeonSweepWorld … -preset hard`, from
 * `-world Nxeon` and no preset) plus the server genuinely creating the new
 * world on disk (`NxeonSweepWorld.fwl`) while keeping the old one — exactly what
 * the apply's own note promises the customer.
 */
const REAL_APPLY_FAMILIES = new Set<string>(["palworld", "minecraft", "rust", "valheim"]);

function familyRealApplyEnabled(family: string): boolean {
  return REAL_APPLY_ENABLED || REAL_APPLY_FAMILIES.has(family);
}

const CONNECT_TIMEOUT_MS = 15_000;
const EXEC_TIMEOUT_MS = 30_000;

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[game-config] notify failed", e);
  }
}

export async function gameConfigApply(job: Job): Promise<void> {
  const serverId = job.serverId;
  if (!serverId) throw new Error("game config: job has no serverId");

  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true },
  });

